head.script:
	scwin.onpageload = function() {
		//inputCalendar1.setValue("20250101");
	};

	scwin.inputCalendar1_onchange = function(e) {
		console.log("inputCalendar1.getFormattedValue:", inputCalendar1.getFormattedValue());
		console.log("inputCalendar1.getValue:", inputCalendar1.getValue());
		console.log("dataMap1.get('key1') : " + dataMap1.get('key1'));
	};
	scwin.trigger1_onclick = function() {
		// -> displayFormat editFormat에 먹힘
		inputCalendar1.setIoFormat("yyyyMMdd", "yyyy/MM/dd");
	}
	scwin.trigger2_onclick = function() {
		// -> displayFormat editFormat에 안먹힘. 여전히 delimiter 사용 (editPlaceholderChar 미사용시)
		// -> displayFormat editFormat에 먹힘 (editPlaceholderChar 사용시)
		inputCalendar1.setCalendarValueType("yearMonth", {"displayFormat" : "yyyy/MM"});
	}
	scwin.trigger3_onclick = function() {
		// -> displayFormat editFormat에 먹힘
		inputCalendar1.setDisplayFormat("yyyy/MM/dd");
	}
	scwin.trigger4_onclick = function() {
		inputCalendar1.setEditPlaceholderChar("");
	}
	scwin.trigger5_onclick = function() {
		var result = inputCalendar1.getEditPlaceholderChar();
		console.log("getEditPlaceholderChar : " + result);
		window.checkResult = result
	}
	scwin.trigger6_onclick = function() {
		var result = inputCalendar1.setValue("20240101");
	}
	scwin.trigger7_onclick = function() {
		var result = inputCalendar1.getValue();
		console.log("getValue : " + result);
	}
	scwin.trigger8_onclick = function() {
		var result = inputCalendar1.getFormattedValue();
		console.log("getFormattedValue : " + result);
	}
	scwin.trigger9_onclick = function(e) {
		dataMap1.set("key1", "20240105");
	}
	scwin.trigger10_onclick = function(e) {
		var result = dataMap1.get("key1");
		console.log("dataMap1.get('key1') : " + result);
	}


scwin.checkVal1 = function() {
	return window.checkResult == '_';
}
scwin.checkVal2 = function() {
	return window.checkResult == '';
}	
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
	WebSquare.wUnit.addCommand("pause", "500");	
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
	WebSquare.wUnit.addCommand("pause", "500");			

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
